tool_input.command:
node --input-type=module -e "
import { toUtcMs } from './src/api.js';
import { dueReminders } from './src/scheduler.js';
const r = { id: 1, sent: 0, tz_offset_min: 330, due_ms: toUtcMs('2026-03-01T09:00', 330) };
const firstDue = (r) => { for (let t = r.due_ms - 864e5; t <= r.due_ms + 864e5; t += 6e4) if (dueReminders([r], t).length) return new Date(t).toISOString(); };
console.log('IST 09:00 -> intended UTC', new Date(r.due_ms).toISOString(), 'fires at', firstDue(r));
const ny = { ...r, tz_offset_min: -300, due_ms: toUtcMs('2026-03-01T09:00', -300) };
console.log('NY 09:00  -> intended UTC', new Date(ny.due_ms).toISOString(), 'fires at', firstDue(ny));
const f = new Intl.DateTimeFormat('en-US', { timeZone: 'America/New_York', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
console.log('node', process.version, 'Intl NY 2026-03-08T07:30Z ->', f.format(Date.parse('2026-03-08T07:30:00Z')), '| 2026-03-07T07:30Z ->', f.format(Date.parse('2026-03-07T07:30:00Z')));
"; node --test test/ 2>&1 | tail -8
